package com.agenda.clinica.repository;
import com.agenda.clinica.entity.Cita; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.time.LocalDateTime; import java.util.*;
public interface CitaRepository extends JpaRepository<Cita,Long> { @Query("select c from Cita c join fetch c.paciente join fetch c.medico m join fetch m.especialidad where c.inicio < :hasta and c.fin > :desde and c.estado <> 'CANCELADA' order by c.inicio") List<Cita> agenda(@Param("desde") LocalDateTime desde,@Param("hasta") LocalDateTime hasta); @Query("select count(c)>0 from Cita c where c.estado <> 'CANCELADA' and c.inicio < :fin and c.fin > :inicio and (c.medico.id=:medicoId or c.paciente.id=:pacienteId)") boolean existeCruce(@Param("inicio") LocalDateTime inicio,@Param("fin") LocalDateTime fin,@Param("medicoId") Long medicoId,@Param("pacienteId") Long pacienteId); }
